const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const stFrancis = ee.Geometry.Point([-101.8005, 39.7755]);
  const deathValley = ee.Geometry.Point([-116.8237, 36.5322]);
  const date = '2025-06-24';
  const nextDay = '2025-06-25';

  // 2. Data Acquisition - MODIS Daily LST
  function getTempAtPoint(point) {
    // Try MODIS Terra first
    let col = ee.ImageCollection('MODIS/061/MOD11A1')
                .filterDate(date, nextDay)
                .filterBounds(point);

    if (col.size().getInfo() === 0) {
      // Fallback to MODIS Aqua
      col = ee.ImageCollection('MODIS/061/MYD11A1')
              .filterDate(date, nextDay)
              .filterBounds(point);
    }

    return col.size().getInfo() > 0 ? col.first() : null;
  }

  const imgStFrancis = getTempAtPoint(stFrancis);
  const imgDeathValley = getTempAtPoint(deathValley);

  // Check for empty collections
  if (!imgStFrancis || !imgDeathValley) {
    const countStFrancis = imgStFrancis ? 1 : 0;
    const countDeathValley = imgDeathValley ? 1 : 0;
    console.log(`Images found - St. Francis: ${countStFrancis}, Death Valley: ${countDeathValley}`);
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Extract LST values (band LST_Day_1km, scale 0.02 for Kelvin)
  function extractLST(img, point, name) {
    const lstBand = img.select('LST_Day_1km');

    // Check valid pixel count
    const count = lstBand.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: point,
      scale: 1000,
      maxPixels: 1e9
    }).get('LST_Day_1km').getInfo();

    if (count === 0) {
      console.log(`${name}: No valid pixels (count: 0)`);
      return null;
    }

    // Get mean temperature (Kelvin)
    const meanK = lstBand.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: point,
      scale: 1000,
      maxPixels: 1e9
    }).get('LST_Day_1km').getInfo();

    if (meanK === null) {
      console.log(`${name}: Null value retrieved`);
      return null;
    }

    // Convert to Celsius: scale * 0.02 - 273.15
    const meanC = meanK * 0.02 - 273.15;
    console.log(`${name}: ${meanC.toFixed(2)}°C (pixels: ${count})`);
    return meanC;
  }

  const tempStFrancis = extractLST(imgStFrancis, stFrancis, 'St. Francis');
  const tempDeathValley = extractLST(imgDeathValley, deathValley, 'Death Valley');

  // 4. Validate results
  if (tempStFrancis === null || tempDeathValley === null) {
    console.log('<answer>C2</answer>');
    return;
  }

  // Check for invalid temperature ranges (unrealistic values)
  if (Math.abs(tempStFrancis) > 100 || Math.abs(tempDeathValley) > 100) {
    console.log(`Invalid temps: ${tempStFrancis.toFixed(2)} vs ${tempDeathValley.toFixed(2)}`);
    console.log('<answer>C3</answer>');
    return;
  }

  // 5. Compare and output final answer
  const isHigher = tempStFrancis > tempDeathValley;
  console.log(isHigher ? '<answer>A</answer>' : '<answer>B</answer>');
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
